spec.expr:
(
  sum(rate(http_server_requests_seconds_count{
    application="healyx",
    status=~"2..",
    uri!~"/actuator.*|/swagger.*|/v3.*",
    uri!="UNKNOWN",
    uri!~"/\\*\\*"
  }[5m]))
/
  sum(rate(http_server_requests_seconds_count{
    application="healyx",
    uri!~"/actuator.*|/swagger.*|/v3.*",
    uri!="UNKNOWN",
    uri!~"/\\*\\*"
  }[5m]))
) * 100
unless
sum(rate(http_server_requests_seconds_count{
  application="healyx",
  uri!~"/actuator.*|/swagger.*|/v3.*",
  uri!="UNKNOWN",
  uri!~"/\\*\\*"
}[5m])) == 0

topk(
  10,
  sum by(uri)(
    rate(http_server_requests_seconds_count{
      application="healyx",
      uri!="UNKNOWN",
      uri!~"/actuator.*|/swagger.*|/v3.*"
    }[5m])
  ) * 60
)

(
  (
    sum(rate(http_server_requests_seconds_sum{
      application="healyx",
      uri!~"/actuator.*|/swagger.*|/v3.*"
    }[5m]))
  /
    sum(rate(http_server_requests_seconds_count{
      application="healyx",
      uri!~"/actuator.*|/swagger.*|/v3.*"
    }[5m]))
  ) * 1000
)
or vector(0)

count(
  (
    sum by (uri) (
      increase(http_server_requests_seconds_count{
        application="healyx",
        uri!="UNKNOWN",
        uri!~"/actuator.*|/swagger.*|/v3.*"
      }[5m])
    )
  ) > 0
)
